<?php
session_start();include '../koneksi.php';if(!isset($_SESSION['login'])||$_SESSION['role']!='kasir'){header('Location: ../login.php');exit;}$uid=(int)$_SESSION['id_user'];$dari=$_GET['dari']??'';$sampai=$_GET['sampai']??'';$a=mysqli_real_escape_string($koneksi,$dari);$b=mysqli_real_escape_string($koneksi,$sampai);$data=mysqli_query($koneksi,"SELECT p.id_penjualan,p.tanggal,COALESCE(pl.nama,'Pelanggan Umum') nama,COALESCE(SUM(d.subtotal),0) total FROM penjualan p LEFT JOIN pelanggan pl ON p.id_pelanggan=pl.id_pelanggan LEFT JOIN detail_penjualan d ON p.id_penjualan=d.id_penjualan WHERE p.id_user=$uid AND p.tanggal BETWEEN '$a' AND '$b' GROUP BY p.id_penjualan ORDER BY p.id_penjualan DESC");$total=0;
?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><title>Laporan Kasir Mebel Jaya</title><link rel="stylesheet" href="../css/bootstrap.min.css"></head><body onload="window.print()"><div class="container py-4"><h3 class="fw-bold">Laporan Penjualan Mebel Jaya</h3><p>Periode <?=htmlspecialchars($dari)?> s/d <?=htmlspecialchars($sampai)?></p><table class="table table-bordered"><thead><tr><th>No</th><th>Invoice</th><th>Tanggal</th><th>Pelanggan</th><th>Total</th></tr></thead><tbody><?php $no=1; while($d=mysqli_fetch_assoc($data)): $total += $d['total']; ?><tr><td><?=$no++?></td><td>INV-<?=str_pad($d['id_penjualan'],4,'0',STR_PAD_LEFT)?></td><td><?=$d['tanggal']?></td><td><?=htmlspecialchars($d['nama'])?></td><td>Rp <?=number_format($d['total'],0,',','.')?></td></tr><?php endwhile; ?></tbody><tfoot><tr><th colspan="4" class="text-end">Total Pendapatan</th><th>Rp <?=number_format($total,0,',','.')?></th></tr></tfoot></table></div></body></html>